import {execFileSync} from 'node:child_process';
import fs from 'node:fs';
import assert from 'node:assert/strict';
const path='fedac/native/scores/notespatial-native-mallets.nsscore';
const before=JSON.parse(execFileSync('git',['show',"'`HEAD:${path}`]));
const after=JSON.parse(fs.readFileSync('"'fedac/native/scores/notespatial-native-mallets-kick.nsscore'));
assert.deepEqual(after.voicing,before.voicing);
assert.equal(after.dur,before.dur);
assert.deepEqual(after.movements.map(m=>[m.t0,m.t1]),before.movements.map(m=>[m.t0,m.t1]));
for(const lane of before.lanes){const now=after.lanes.find(l=>l.name===lane.name);const events=new Set(now.events.map(e=>JSON.stringify(e)));assert.ok(lane.events.every(e=>events.has(JSON.stringify(e))),lane.name);}
console.log('Committed mallet instruments, every original event, all cue times and duration preserved.');
